const d = $input.first().json;
const days = { Monthly: 30, Quarterly: 90, Yearly: 365 }[d['Plan']] || 30;
const join = new Date();
const exp = new Date(join.getTime() + days * 86400000);
const fmt = x => x.toISOString().slice(0, 10);
let phone = String(d['WhatsApp Number']).replace(/\D/g, '');
if (phone.startsWith('0')) phone = '92' + phone.slice(1);
return [{ json: {
  name: d['Full Name'],
  phone,
  plan: d['Plan'],
  fee: d['Fee Paid'] || 0,
  joinDate: fmt(join),
  expiryDate: fmt(exp),
  status: 'Active'
} }];

const today = new Date();
today.setHours(0, 0, 0, 0);
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  if (!r.Expiry || r.Status === 'Expired') continue;
  const diff = Math.round((new Date(r.Expiry) - today) / 86400000);
  if (diff === 3 || diff === 0) {
    out.push({ json: { name: r.Name, phone: String(r.Phone), expiry: r.Expiry, daysLeft: diff } });
  }
}
return out;

const rows = $input.all().map(i => i.json);
const today = new Date();
today.setHours(0, 0, 0, 0);
const weekAgo = new Date(today.getTime() - 7 * 86400000);
let active = 0, expired = 0, newJoins = 0, expiringSoon = 0, revenue = 0;
for (const r of rows) {
  if (!r.Expiry) continue;
  const diff = Math.round((new Date(r.Expiry) - today) / 86400000);
  if (diff < 0) expired++; else active++;
  if (diff >= 0 && diff <= 7) expiringSoon++;
  if (r['Join Date'] && new Date(r['Join Date']) >= weekAgo) {
    newJoins++;
    revenue += Number(r.Fee) || 0;
  }
}
return [{ json: { total: rows.length, active, expired, newJoins, expiringSoon, revenue } }];

